<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence\Doctrine\QuestionLearning;
use App\Domain\QuestionLearning\Entity\LearningEvent;use App\Domain\QuestionLearning\Enum\LearningEventType;use App\Domain\QuestionLearning\Enum\LearningOutcome;use App\Domain\QuestionLearning\Repository\LearningEventRepositoryInterface;use App\Infrastructure\Persistence\Doctrine\QuestionLearning\Entity\LearningEventRecord;use Doctrine\ORM\EntityManagerInterface;
final class DoctrineLearningEventRepository implements LearningEventRepositoryInterface { public function __construct(private readonly EntityManagerInterface $entityManager) {} public function append(LearningEvent $event): void { $record=new LearningEventRecord();$record->id=$event->id;$record->userId=$event->userId;$record->questionId=$event->questionId;$record->attemptId=$event->attemptId;$record->taxonomySubjectId=$event->taxonomySubjectId;$record->type=$event->type->value;$record->outcome=$event->outcome?->value;$record->elapsedSeconds=$event->elapsedSeconds;$record->origin=$event->origin;$record->payload=$event->payload;$record->occurredAt=$event->occurredAt;$this->entityManager->persist($record); $this->entityManager->flush(); } public function listForUserSubject(string $userId,string $taxonomySubjectId,\DateTimeImmutable $since):array { return array_map(static fn(LearningEventRecord $record):LearningEvent=>new LearningEvent($record->id,$record->userId,$record->questionId,$record->attemptId,$record->taxonomySubjectId,LearningEventType::from($record->type),$record->outcome===null?null:LearningOutcome::from($record->outcome),$record->elapsedSeconds,$record->origin,$record->payload,$record->occurredAt),$this->entityManager->createQueryBuilder()->select('event')->from(LearningEventRecord::class,'event')->where('event.userId=:userId')->andWhere('event.taxonomySubjectId=:subjectId')->andWhere('event.occurredAt>=:since')->setParameter('userId',$userId)->setParameter('subjectId',$taxonomySubjectId)->setParameter('since',$since)->orderBy('event.occurredAt','ASC')->getQuery()->getResult()); } }
